// Obtener el mensaje principal
const message = items[0].json.body;

// Texto del mensaje
const content = message.content || "";

// Adjuntos
const attachments = message.attachments || [];

// Regex → generar URL interna
function makeInternal(url) {
  if (!url) return url;

  return url.replace(
    /^https:\/\/([a-zA-Z0-9\-]+)\.ocm\.aigentss\.cloud/,
    'http://$1.ocm.aigentss.cloud:3000'
  );
}

// ------------------------------------
// Procesar TODOS los attachments
// ------------------------------------
const processedAttachments = attachments.map(att => ({
  ...att,
  data_url_external: att.data_url || null,
  data_url_internal: makeInternal(att.data_url),
  thumb_url_external: att.thumb_url || null,
  thumb_url_internal: makeInternal(att.thumb_url)
}));

// ------------------------------------
// Detectar tipos presentes en el mensaje
// ------------------------------------
let type = "unknown";

// Caso: solo texto
if (attachments.length === 0 && content.trim() !== "") {
  type = "text";

// Caso: hay adjuntos
} else if (attachments.length > 0) {

  // Si TODOS son imágenes
  if (attachments.every(a => a.file_type === "image")) {
    type = content.trim() !== "" ? "image_with_text" : "image";
  }

  // Si TODOS son audios
  else if (attachments.every(a => a.file_type === "audio")) {
    type = "audio";

  // Si TODOS son location
  } else if (attachments.every(a => a.file_type === "location")) {
    type = "location";

  // Mezcla de adjuntos → híbrido
  } else {
    type = "mixed";
  }
}

return [
  {
    json: {
      type,
      content_text: content,
      attachments: processedAttachments,
      raw: items[0].json
    }
  }
];

const node = items[0].json;
const editFields = $('Edit Fields').item.json;

// Extraer coordenadas del attachment
const attachment = node.attachments?.[0] || {};
const lat = attachment.coordinates_lat || null;
const lon = attachment.coordinates_long || null;

// Construir el content_text para el siguiente nodo
//const content = {
//  lat,
//  lon
//};
const content = `${lat}, ${lon}`;

let result = {
  type: node.type,
  content: content,   // aquí va listo para el agente
  raw: editFields
};

return [{ json: result }];

const out = [];

for (const item of $input.all()) {
  const type = item.json.type;

  if (type === "text" || type === "image_with_text") {
    out.push({
      json: {
        content: item.json.content_text,
        type: "text"
      }
    });
  } else {
    out.push(item);
  }
}

return out;

const node = items[0].json;
const editFields = $('Edit Fields').item.json;

let result = {
  type: node.type,
  content_text: node.content,
  raw: editFields

};

return [{ json: result }];

const msgs = $json.output.messages || [];

return msgs.map((m, i) => ({
  indx: i,
  sms: m.sms || "",
  url: m.url || "",
  hasUrl: Boolean(m.url && m.url.trim() !== "")
}));

const out = { ...$json };

// Asegura existencia de la estructura
out.contact_context = out.contact_context || {};
out.contact_context.custom_attributes = out.contact_context.custom_attributes || {};

// Setea SOLO el atributo necesario
out.contact_context.custom_attributes.terms_accepted = true;
out.contact_context.custom_attributes.terms_accepted_at =
out.contact_context.custom_attributes.terms_accepted_at ?? new Date().toISOString();
out.contact_context.tac = true;
out.contact_context.tac_accepted_at =
out.contact_context.tac_accepted_at ?? new Date().toISOString();

return [{ json: out }];

const concat = String($json.concat_message ?? '');
const pending = String($json.pending_intent_block ?? '');
const contact = $json.contact_context ?? {};
const convo = $json.conversation ?? {};

const content =
`<<<USER_UTTERANCE>>>
${concat}
<<<END_USER_UTTERANCE>>>

<<<PENDING_INTENT_BLOCK>>>
${pending}
<<<END_PENDING_INTENT_BLOCK>>>

<<<CONTACT_CONTEXT_JSON>>>
${JSON.stringify(contact, null, 2)}
<<<END_CONTACT_CONTEXT_JSON>>>

<<<CONVERSATION_CONTEXT_JSON>>>
${JSON.stringify(convo, null, 2)}
<<<END_CONVERSATION_CONTEXT_JSON>>>`;

const memoryObj = {
  type: "human",
  content,
  additional_kwargs: {},
  response_metadata: {}
};

// IMPORTANTE: guardamos ambas versiones para que el insert sea fácil
return [{
  json: {
    ...$json,
    memory_message_obj: memoryObj,
    memory_message_text: JSON.stringify(memoryObj) // por si tu columna es TEXT
  }
}];

const senderType = String(
  $json.body?.conversation?.messages?.[0]?.sender_type || ''
).toLowerCase();

const isUserMessage =
  $json.body?.event === 'message_created' &&
  (senderType === 'contact' || senderType === 'user');

return [{
  json: {
    ...$json,
    is_user_message: isUserMessage,
    _debug: {
      event: $json.body?.event,
      sender_type: senderType
    }
  }
}];

function stripAccents(s) {
  return String(s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalize(s) {
  return stripAccents(String(s || '').toLowerCase())
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const raw = $json.concat_message ?? '';
const msg = normalize(raw);

const negativePhrases = [
  'no acepto',
  'no autorizo',
  'no estoy de acuerdo',
  'no deseo continuar',
  'no quiero continuar',
  'me niego',
  'no doy permiso'
].map(normalize);

const negativeWords = [
  'rechazo',
  'deniego'
].map(normalize);

const isNegative =
  negativePhrases.some(p => (` ${msg} `).includes(` ${p} `)) ||
  negativeWords.some(w => msg.split(' ').includes(w));

const isEmpty = msg.length === 0;

return [{
  json: {
    ...$json,
    consent_eval: {
      raw,
      normalized: msg,
      is_negative: isNegative,
      is_empty: isEmpty,
      can_continue: !isNegative && !isEmpty
    }
  }
}];
